package co.com.empresa.domain.typecategory;import co.com.empresa.commons.exception.DomainException;import co.com.empresa.domain.constants.DomainErrors;import co.com.empresa.domain.type.ITypeRepository;import co.com.empresa.domain.type.Type;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.Example;import java.util.Collections;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class)class TypeCategoryDomainServiceTest {    @Mock    private ITypeCategoryRepository categoryRepository;    @Mock    private ITypeRepository typeRepository;    @InjectMocks    private TypeCategoryDomainService typeCategoryDomainService;    @Test    @DisplayName("validateUniqueness: Should not throw exception when code is unique")    void validateUniqueness_UniqueCode_Success() {        TypeCategory category = TypeCategory.builder()                .id(1L)                .name("Test Category")                .code("UNIQ_CAT")                .build();        when(categoryRepository.findAll(any(Example.class))).thenReturn(Collections.emptyList());        assertDoesNotThrow(() -> typeCategoryDomainService.validateUniqueness(category));        verify(categoryRepository, times(1)).findAll(any(Example.class));    }    @Test    @DisplayName("validateUniqueness: Should throw exception when duplicate code exists")    void validateUniqueness_DuplicateCode_ThrowsException() {        TypeCategory category = TypeCategory.builder()                .id(1L)                .name("Test Category")                .code("DUP_CAT")                .build();        TypeCategory duplicate = TypeCategory.builder()                .id(2L)                .name("Another Category")                .code("DUP_CAT")                .build();        when(categoryRepository.findAll(any(Example.class))).thenReturn(List.of(duplicate));        DomainException exception = assertThrows(DomainException.class, () -> typeCategoryDomainService.validateUniqueness(category));        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_CODE_DUPLICATE, exception.getMessage());    }    @Test    @DisplayName("validateNoDependencies: Should not throw exception when no types are associated")    void validateNoDependencies_NoTypes_Success() {        TypeCategory category = TypeCategory.builder()                .id(1L)                .build();        when(typeRepository.findAll(any(Example.class))).thenReturn(Collections.emptyList());        assertDoesNotThrow(() -> typeCategoryDomainService.validateNoDependencies(category));        verify(typeRepository, times(1)).findAll(any(Example.class));    }    @Test    @DisplayName("validateNoDependencies: Should throw exception when associated types exist")    void validateNoDependencies_TypesExist_ThrowsException() {        TypeCategory category = TypeCategory.builder()                .id(1L)                .build();        Type associatedType = Type.builder()                .id(100L)                .typeCategoryId(1L)                .build();        when(typeRepository.findAll(any(Example.class))).thenReturn(List.of(associatedType));        DomainException exception = assertThrows(DomainException.class, () -> typeCategoryDomainService.validateNoDependencies(category));        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_HAS_TYPES, exception.getMessage());    }}